  FT["BN-S-16-2023-SUPREME-COURT-ACT-AMENDMENT-ORDER-2023"] = {"id":"BN-S-16-2023-SUPREME-COURT-ACT-AMENDMENT-ORDER-2023","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-09","articleCount":5,"structureMode":"SECTION","title":{"zh":"最高法院法修正命令 2023","en":"SUPREME COURT ACT AMENDMENT ORDER 2023","orig":null},"level":"law","status":"active","docNumber":"S 16/2023","issuingBody":"Attorney General's Chambers, Brunei Darussalam","promulgatedDate":"2023","completenessNote":"来源为 AGC 官方 PDF《S-16-2023-SUPREME-COURT-ACT-AMENDMENT-ORDER-2023.pdf》（4 页），本次切分 5 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-16-2023-SUPREME-COURT-ACT-AMENDMENT-ORDER-2023.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-16-2023-SUPREME-COURT-ACT-AMENDMENT-ORDER-2023-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"This Order may be cited as the Supreme Court Act (Amendment) Order, section 2 of Chapter 5"}},{"id":"BN-S-16-2023-SUPREME-COURT-ACT-AMENDMENT-ORDER-2023-A2","no":2,"noLabel":{"en":"Section 2."},"heading":{"en":"of section 2 of Chapter 5"},"text":{"en":"2 of the Supreme Court Act, in this Order referred to as the Act, is by deleting the definition of \"Judge\" and by substituting the following new definition therefor - \" \"Judge\" means a Judge of the Supreme Court and includes the Chief Justice, President of the Court of Appeal. Vice President of the Court of Appeal and a Judicial Commissioner of the Supreme Court;\". section 4"}},{"id":"BN-S-16-2023-SUPREME-COURT-ACT-AMENDMENT-ORDER-2023-A3","no":3,"noLabel":{"en":"Section 3."},"heading":{"en":"of section 4"},"text":{"en":"is amended by repealing section 4 and by substituting the following new section therefor - \"Constitution of Supreme Court"}},{"id":"BN-S-16-2023-SUPREME-COURT-ACT-AMENDMENT-ORDER-2023-A4","no":4,"noLabel":{"en":"Section 4."},"heading":{"en":"made under Article 83(3))"},"text":{"en":"The Supreme Court shall consist of the Chief Justice, the President. the Vice President, the Judges and the Judicial Commissioners of the Supreme section 6"}},{"id":"BN-S-16-2023-SUPREME-COURT-ACT-AMENDMENT-ORDER-2023-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"(1) The Supreme Court shall be a Court of Record and shall consist of(a} the High Court which shall exercise original and appellate criminal and civil jurisdiction; and\n\n(b) the Court of Appeal which shall exercise appellate criminal and civil jurisdiction.\n\n(2) The Judges of the High Court shall be the Chief Justice and such of Judges as may be prescribed by His Majesty the Sultan and Yang Di-Pertuan in Council.\n\n(3) The criminal and civil jurisdiction of the Court of Appeal shall be exercised by three Judges of the Court of Appeal who shall consist of(a) the Chief Justice who, by virtue of his office, shall be the of the Court of Appeal;\n\n(b) the Vice President of the Court of Appeal; and\n\n(c) such other Judges or Judicial Commissioners of the Supreme\n\n(4) In a sitting of the Court of Appeal(a) the Chief Justice is to preside as the President of the Court of\n\n(b) in the absence of the President, the Vice President of the Court of Appeal shall preside;\n\n(c) in the absence of the President and Vice President, the Chief Justice is to appoint a person to preside.\n\n(5) When a judgment in a proceeding in the Court of Appeal is\n\n(a) it is not necessary for any of the Judges of the Court of Appeal whom it was heard to be present in the Court of Appeal to hand down the judgment;\n\n(b) the opinion of any of the Judges of the Court of Appeal may be to writing and made public by any Judge of the Court of\n\n(c) the judgment of the Court of Appeal has the same effect as if of the Court of Appeal whose opinion is so made public had been present in the Court of Appeal;\n\n(d) the Court of Appeal may be constituted by one or more Judges of the Court of Appeal.\". Made this 28th. day of Ramadhan, 1444 Hijriah corresponding to the of April, 2023 at Our Istana Nurul Iman, Bandar Seri Begawan, Brunei Darussalam.\n\nHIS MAJESTY THE SULTAN AND YANG DI·PERTUAN, DARUSSALAM."}}],"pack":"bn-p14","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"SUPREME COURT ACT AMENDMENT ORDER 2023","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
